package com.bank.docs;

import java.io.*;
import java.util.logging.*;

public class UploadDemo {
    private static final Logger log = Logger.getLogger(UploadDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        long directThreshold = 50L * 1024 * 1024;  // 50 MB
        long absoluteMax = 5L * 1024 * 1024 * 1024; // 5 GB
        UploadHandler handler = new UploadHandler(directThreshold, absoluteMax);

        // Scenario 1: Rajesh's 40 MB packet — within limits, STREAMED (bounded memory)
        InputStream fortyMb = new SizedStream(40L * 1024 * 1024);
        UploadOutcome o1 = handler.handle("SAV2001", "loan_packet.pdf", fortyMb, 40L * 1024 * 1024);
        log.info("Rajesh outcome: " + o1.mode + " — " + o1.detail);

        // Scenario 2: Priya's 3 GB archive — above direct threshold → presigned direct-to-S3
        UploadOutcome o2 = handler.handle("CUR3001", "archive.zip", null, 3L * 1024 * 1024 * 1024);
        log.info("Priya outcome: " + o2.mode + " — " + o2.detail);

        // Scenario 3: 6 GB file — over absolute cap → rejected (413)
        try {
            handler.handle("SAV2001", "massive.iso", null, 6L * 1024 * 1024 * 1024);
        } catch (PayloadTooLargeException e) {
            log.severe("413 rejected: " + e.getMessage());
        }
    }
}

// ─── model/UploadOutcome.java ───
class UploadOutcome {
    final String mode, detail;
    UploadOutcome(String mode, String detail) { this.mode = mode; this.detail = detail; }
}
class PayloadTooLargeException extends RuntimeException { PayloadTooLargeException(String m) { super(m); } }

// ─── handler/UploadHandler.java ───
// Decides: stream through server (bounded memory) OR route to presigned direct upload.
class UploadHandler {
    private static final Logger log = Logger.getLogger(UploadHandler.class.getName());
    private static final int CHUNK = 8 * 1024;   // 8 KB — only one chunk in memory at a time
    private final long directThreshold, absoluteMax;

    UploadHandler(long directThreshold, long absoluteMax) {
        this.directThreshold = directThreshold; this.absoluteMax = absoluteMax;
    }

    UploadOutcome handle(String userId, String filename, InputStream in, long sizeBytes) throws IOException {
        if (sizeBytes > absoluteMax)
            throw new PayloadTooLargeException(filename + " size " + sizeBytes + " exceeds cap " + absoluteMax);

        if (sizeBytes > directThreshold) {
            // Truly large: do NOT pass bytes through the server — mint presigned URL.
            String key = userId + "/" + filename;
            String url = "https://nbi-docs.s3.amazonaws.com/" + key + "?X-Amz-Signature=SIM";
            return new UploadOutcome("DIRECT_PRESIGNED", "client uploads straight to S3: " + url);
        }

        // Modest size: STREAM the InputStream chunk-by-chunk — NEVER getBytes().
        long copied = streamToStorage(in, userId + "/" + filename);
        return new UploadOutcome("STREAMED", "streamed " + copied + " bytes, heap stayed bounded");
    }

    // Copies input to output using a small fixed buffer. Memory use is O(CHUNK), not O(file).
    private long streamToStorage(InputStream in, String key) throws IOException {
        long total = 0;
        byte[] buf = new byte[CHUNK];
        try (OutputStream out = new NullStorageOutputStream(key)) {   // real impl: S3 stream / file
            int n;
            while ((n = in.read(buf)) != -1) {
                out.write(buf, 0, n);     // one 8KB chunk at a time
                total += n;
            }
        }
        log.fine(() -> "streamed to " + key);
        return total;
    }
}

// ─── Simulates an InputStream of a given size without allocating it all ───
class SizedStream extends InputStream {
    private long remaining;
    SizedStream(long size) { this.remaining = size; }
    @Override public int read() { if (remaining <= 0) return -1; remaining--; return 0; }
    @Override public int read(byte[] b, int off, int len) {
        if (remaining <= 0) return -1;
        int n = (int) Math.min(len, remaining);
        remaining -= n;
        return n;
    }
}

// ─── Simulates writing to storage without keeping bytes ───
class NullStorageOutputStream extends OutputStream {
    NullStorageOutputStream(String key) { }
    @Override public void write(int b) { }
    @Override public void write(byte[] b, int off, int len) { }
}

// ─── Clean log formatter ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$-7s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
