// ─── config/MultipartConfig.java (programmatic limits) ───
@Configuration
public class MultipartConfig {
    @Bean
    public MultipartConfigElement multipartConfigElement() {
        MultipartConfigFactory f = new MultipartConfigFactory();
        f.setMaxFileSize(DataSize.ofMegabytes(50));
        f.setMaxRequestSize(DataSize.ofMegabytes(60));
        f.setFileSizeThreshold(DataSize.ofKilobytes(256)); // spill to disk, protect heap
        return f.createMultipartConfig();
    }
}

